    resize: none;
    background: #2d2f33;
    border: 1px solid #444;
    border-radius: 6px;
    color: #d1d2d3;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #1264a3;
}

.message-input-area textarea::placeholder {
    color: #8a8b8e;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 18px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #148567;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

/* ── No Channel Selected ── */
.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #8a8b8e;
    font-size: 1.1rem;
}

/* ── Thread Panel ── */
.thread-panel {
    width: 25%;
    min-width: 260px;
    background: #222529;
    border-left: 1px solid #333;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #333;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: transparent;
    border: none;
    color: #9a9b9e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 2px 6px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #3a3d42;
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    background: #2d2f33;
    border-bottom: 1px solid #333;
    flex-shrink: 0;
}

.thread-root-quote .author {
    font-size: 0.85rem;
}

.thread-root-quote p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #d1d2d3;
    line-height: 1.4;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding: 6px 10px;
}
"}

